pt:
//【茶々丸】
<voice name='茶々丸' class='茶々丸' src='voice/md03/0180470a07'>
//「でも、これがヒトじゃないのは見てわかる
//でしょ？」
"Mas dá pra ver que ela não é humana, não dá?"

en:
//【景明】
<voice name='景明' class='景明' src='voice/md03/0180480a00'>
//「……ああ」
"...Yes."

pt:
//【景明】
<voice name='景明' class='景明' src='voice/md03/0180480a00'>
//「……ああ」
"...Sim."

en:
//　やむなく認めて、首肯する。
